export default {
  "apply.ts": "import { DESIGNS, type DeclaredIntent, type WishlistDesign } from \"./manifest.ts\";\n\n/**\n * Applies one wishlist design to a checkout of the canonical Acme Shop source. Pure: the caller\n * supplies the fixture files and reads the base. Used by the integration Worker (which commits the\n * result to an Artifacts fork).\n */\n\nexport type DesignChanges = {\n  /** Repository path to new full content, for every added or edited file. */\n  files: Record<string, string>;\n  added: string[];\n  modified: string[];\n  intent: DeclaredIntent;\n};\n\n/**\n * @param fixture Fixture files keyed by path relative to `fixtures/wishlist` (`files/shared/...`).\n * @param readBase Returns the base content of a repository file, or null when it does not exist.\n * Throws when an edit anchor is missing or ambiguous, or when an added file already exists: the\n * fixture then does not apply to this base, and nothing must be committed.\n */\nexport function applyDesign(\n  design: WishlistDesign,\n  fixture: Readonly<Record<string, string>>,\n  readBase: (path: string) => string | null,\n): DesignChanges {\n  const spec = DESIGNS[design];\n  const files: Record<string, string> = {};\n  const added: string[] = [];\n  for (const source of spec.sources) {\n    const prefix = `files/${source}/`;\n    for (const [key, content] of Object.entries(fixture)) {\n      if (!key.startsWith(prefix)) continue;\n      const path = key.slice(prefix.length);\n      if (!(path in files)) {\n        if (readBase(path) !== null) throw new Error(`${path} already exists in the base`);\n        added.push(path);\n      }\n      files[path] = content;\n    }\n  }\n  if (added.length === 0) throw new Error(`fixture design ${design} has no files`);\n\n  const modified: string[] = [];\n  for (const edit of spec.edits) {\n    const current = files[edit.path] ?? readBase(edit.path);\n    if (current === null || current === undefined) throw new Error(`${edit.path} is missing`);\n    const at = current.indexOf(edit.find);\n    if (at === -1 || current.indexOf(edit.find, at + 1) !== -1) {\n      throw new Error(`${edit.path}: anchor not found exactly once: ${JSON.stringify(edit.find)}`);\n    }\n    files[edit.path] = current.slice(0, at) + edit.replace + current.slice(at + edit.find.length);\n    if (!modified.includes(edit.path)) modified.push(edit.path);\n  }\n\n  const expectedFiles = [...added, ...modified].sort();\n  return {\n    files,\n    added: added.sort(),\n    modified: modified.sort(),\n    intent: { ...spec.intent, expectedFiles },\n  };\n}\n",
  "files/design-a/src/wishlist/model.ts": "// Design A: normalized, mutable relational tables.\n//\n// Wishlists, collaborator memberships, share links, and items are separate tables of rows. A\n// membership row is updated in place when a collaborator is removed or a link is revoked, so the\n// table always holds the current truth and nothing is denormalized. Effective access is derived on\n// every request from the collaborator table: there is no cached membership to keep in sync.\nimport {\n  err,\n  type Lookup,\n  ok,\n  type Result,\n  type Role,\n  type SeedWishlist,\n  validName,\n  type WishlistView,\n} from \"./types\";\n\nexport type WishlistRow = { id: string; ownerId: string; name: string; createdAt: number };\nexport type CollaboratorRow = {\n  wishlistId: string;\n  userId: string;\n  role: Role;\n  /** Share link token the member joined with; null for the owner. */\n  viaLink: string | null;\n  active: boolean;\n  updatedAt: number;\n};\nexport type ShareLinkRow = {\n  token: string;\n  wishlistId: string;\n  active: boolean;\n  updatedAt: number;\n};\nexport type ItemRow = { wishlistId: string; productId: string; addedBy: string; addedAt: number };\n\nexport type WishlistState = {\n  wishlists: WishlistRow[];\n  collaborators: CollaboratorRow[];\n  shareLinks: ShareLinkRow[];\n  items: ItemRow[];\n};\n\nexport function createWishlistState(): WishlistState {\n  return { wishlists: [], collaborators: [], shareLinks: [], items: [] };\n}\n\nconst findWishlist = (s: WishlistState, id: string) => s.wishlists.find((w) => w.id === id);\n\n// SELECT role FROM collaborators WHERE wishlist_id = ? AND user_id = ? AND active\nfunction roleOf(s: WishlistState, wishlistId: string, userId: string): Role | null {\n  const row = s.collaborators.find(\n    (r) => r.wishlistId === wishlistId && r.userId === userId && r.active,\n  );\n  return row ? row.role : null;\n}\n\n/** The wishlist plus the caller's current role, read from the membership table. */\nfunction access(s: WishlistState, id: string, userId: string) {\n  const wishlist = findWishlist(s, id);\n  if (!wishlist) return err<{ wishlist: WishlistRow; role: Role }>(\"not_found\");\n  const role = roleOf(s, id, userId);\n  return role ? ok({ wishlist, role }) : err<{ wishlist: WishlistRow; role: Role }>(\"forbidden\");\n}\n\nexport function createWishlist(s: WishlistState, ownerId: string, name: unknown): Result<string> {\n  if (!validName(name)) return err(\"invalid_name\");\n  const now = Date.now();\n  const id = `wl_${crypto.randomUUID()}`;\n  s.wishlists.push({ id, ownerId, name: name.trim(), createdAt: now });\n  s.collaborators.push({\n    wishlistId: id,\n    userId: ownerId,\n    role: \"owner\",\n    viaLink: null,\n    active: true,\n    updatedAt: now,\n  });\n  return ok(id);\n}\n\nexport function viewWishlist(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  lookup: Lookup,\n): Result<WishlistView> {\n  const found = access(s, id, userId);\n  if (!found.ok) return found;\n  const { wishlist } = found.value;\n  // Items join products and the adder's current membership row.\n  const items = s.items\n    .filter((i) => i.wishlistId === id)\n    .map((i) => {\n      const product = lookup(i.productId);\n      return {\n        productId: i.productId,\n        name: product?.name ?? \"Unknown product\",\n        priceCents: product?.priceCents ?? 0,\n        addedBy: i.addedBy,\n        addedByRole: roleOf(s, id, i.addedBy),\n      };\n    });\n  const collaborators = s.collaborators\n    .filter((r) => r.wishlistId === id && r.active)\n    .map((r) => ({ userId: r.userId, role: r.role }))\n    .sort((a, b) =>\n      a.role === b.role ? a.userId.localeCompare(b.userId) : a.role === \"owner\" ? -1 : 1,\n    );\n  return ok({\n    id,\n    name: wishlist.name,\n    owner: wishlist.ownerId,\n    collaborators,\n    items,\n    itemCount: items.length,\n  });\n}\n\nexport function shareWishlist(s: WishlistState, id: string, userId: string): Result<string> {\n  const found = access(s, id, userId);\n  if (!found.ok) return found;\n  if (found.value.role !== \"owner\") return err(\"forbidden\");\n  const existing = s.shareLinks.find((l) => l.wishlistId === id && l.active);\n  if (existing) return ok(existing.token);\n  const token = crypto.randomUUID();\n  s.shareLinks.push({ token, wishlistId: id, active: true, updatedAt: Date.now() });\n  return ok(token);\n}\n\n/** Deactivates the link and, in place, every membership row that joined through it. */\nexport function revokeShareLink(s: WishlistState, id: string, userId: string): Result<null> {\n  const found = access(s, id, userId);\n  if (!found.ok) return found;\n  if (found.value.role !== \"owner\") return err(\"forbidden\");\n  const now = Date.now();\n  for (const link of s.shareLinks) {\n    if (link.wishlistId !== id || !link.active) continue;\n    link.active = false;\n    link.updatedAt = now;\n    for (const row of s.collaborators) {\n      if (row.wishlistId === id && row.viaLink === link.token && row.active) {\n        row.active = false;\n        row.updatedAt = now;\n      }\n    }\n  }\n  return ok(null);\n}\n\nexport function joinByLink(s: WishlistState, token: string, userId: string): Result<string> {\n  const link = s.shareLinks.find((l) => l.token === token && l.active);\n  if (!link) return err(\"invalid_link\");\n  const id = link.wishlistId;\n  if (roleOf(s, id, userId)) return ok(id);\n  const row = s.collaborators.find((r) => r.wishlistId === id && r.userId === userId);\n  const now = Date.now();\n  if (row) {\n    // Rejoining reuses the membership row: UPDATE ... SET active = 1.\n    row.active = true;\n    row.role = \"editor\";\n    row.viaLink = token;\n    row.updatedAt = now;\n  } else {\n    s.collaborators.push({\n      wishlistId: id,\n      userId,\n      role: \"editor\",\n      viaLink: token,\n      active: true,\n      updatedAt: now,\n    });\n  }\n  return ok(id);\n}\n\nexport function addItem(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  productId: string,\n  lookup: Lookup,\n): Result<null> {\n  const found = access(s, id, userId);\n  if (!found.ok) return found;\n  if (!lookup(productId)) return err(\"unknown_product\");\n  if (s.items.some((i) => i.wishlistId === id && i.productId === productId)) return ok(null);\n  s.items.push({ wishlistId: id, productId, addedBy: userId, addedAt: Date.now() });\n  return ok(null);\n}\n\nexport function removeItem(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  productId: string,\n): Result<null> {\n  const found = access(s, id, userId);\n  if (!found.ok) return found;\n  const index = s.items.findIndex((i) => i.wishlistId === id && i.productId === productId);\n  if (index === -1) return err(\"not_in_wishlist\");\n  s.items.splice(index, 1);\n  return ok(null);\n}\n\nexport function removeCollaborator(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  targetId: string,\n): Result<null> {\n  const found = access(s, id, userId);\n  if (!found.ok) return found;\n  if (found.value.role !== \"owner\") return err(\"forbidden\");\n  const row = s.collaborators.find(\n    (r) => r.wishlistId === id && r.userId === targetId && r.role === \"editor\" && r.active,\n  );\n  if (!row) return err(\"not_a_collaborator\");\n  row.active = false;\n  row.updatedAt = Date.now();\n  return ok(null);\n}\n\n/** Bulk load: inserts rows as given, without per-row checks. */\nexport function importWishlists(s: WishlistState, rows: readonly SeedWishlist[]): void {\n  const now = Date.now();\n  for (const w of rows) {\n    s.wishlists.push({ id: w.id, ownerId: w.ownerId, name: w.name, createdAt: now });\n    s.collaborators.push({\n      wishlistId: w.id,\n      userId: w.ownerId,\n      role: \"owner\",\n      viaLink: null,\n      active: true,\n      updatedAt: now,\n    });\n    if (w.shareToken) {\n      s.shareLinks.push({ token: w.shareToken, wishlistId: w.id, active: true, updatedAt: now });\n    }\n    for (const userId of w.collaborators) {\n      s.collaborators.push({\n        wishlistId: w.id,\n        userId,\n        role: \"editor\",\n        viaLink: w.shareToken,\n        active: true,\n        updatedAt: now,\n      });\n    }\n    for (const item of w.items) {\n      s.items.push({\n        wishlistId: w.id,\n        productId: item.productId,\n        addedBy: item.addedBy,\n        addedAt: now,\n      });\n    }\n  }\n}\n",
  "files/design-a/test/wishlist.model.test.ts": "// Design A: membership rows are updated in place; access is read from the current rows.\nimport { expect, test } from \"bun:test\";\nimport { SEED_PRODUCTS } from \"../src/catalog\";\nimport {\n  addItem,\n  createWishlist,\n  createWishlistState,\n  joinByLink,\n  revokeShareLink,\n  shareWishlist,\n  viewWishlist,\n} from \"../src/wishlist/model\";\n\nconst lookup = (id: string) => SEED_PRODUCTS.find((p) => p.id === id);\nconst must = <T>(r: { ok: true; value: T } | { ok: false; error: string }): T => {\n  if (!r.ok) throw new Error(r.error);\n  return r.value;\n};\n\ntest(\"revoking a link deactivates its membership rows in place\", () => {\n  const s = createWishlistState();\n  const id = must(createWishlist(s, \"alice\", \"Gifts\"));\n  const token = must(shareWishlist(s, id, \"alice\"));\n  must(joinByLink(s, token, \"bob\"));\n  expect(s.collaborators).toHaveLength(2);\n\n  must(revokeShareLink(s, id, \"alice\"));\n  expect(s.collaborators).toHaveLength(2);\n  expect(s.collaborators.find((r) => r.userId === \"bob\")?.active).toBe(false);\n  expect(s.shareLinks.every((l) => !l.active)).toBe(true);\n  expect(addItem(s, id, \"bob\", \"p-100\", lookup)).toEqual({ ok: false, error: \"forbidden\" });\n});\n\ntest(\"rejoining through a new link reactivates the same row\", () => {\n  const s = createWishlistState();\n  const id = must(createWishlist(s, \"alice\", \"Gifts\"));\n  must(joinByLink(s, must(shareWishlist(s, id, \"alice\")), \"bob\"));\n  must(revokeShareLink(s, id, \"alice\"));\n  must(joinByLink(s, must(shareWishlist(s, id, \"alice\")), \"bob\"));\n  expect(s.collaborators.filter((r) => r.userId === \"bob\")).toHaveLength(1);\n  expect(must(viewWishlist(s, id, \"bob\", lookup)).collaborators).toHaveLength(2);\n});\n",
  "files/design-b/src/wishlist/model.ts": "// Design B: append-only membership event log with a materialized current-member set.\n//\n// Every membership change (created, joined, removed, link created, link revoked) is appended to\n// `log` and never edited. `apply` folds each event into the materialized view in the same step, so\n// reads use the current member set directly and never recompute access from history. The view can\n// always be rebuilt from the log (`replay`); concurrent membership changes are ordered by `seq`.\nimport {\n  err,\n  type Lookup,\n  ok,\n  type Result,\n  type Role,\n  type SeedWishlist,\n  validName,\n  type WishlistView,\n} from \"./types\";\n\nexport type MembershipEvent = Readonly<\n  | { seq: number; type: \"created\"; wishlistId: string; userId: string; name: string }\n  | { seq: number; type: \"joined\"; wishlistId: string; userId: string; via: string }\n  | { seq: number; type: \"removed\"; wishlistId: string; userId: string }\n  | { seq: number; type: \"link_created\"; wishlistId: string; token: string }\n  | { seq: number; type: \"link_revoked\"; wishlistId: string; token: string }\n>;\n\ntype Member = { role: Role; via: string | null };\n\n/** Current state derived from the log. Rebuildable at any time with `replay`. */\nexport type MembershipView = {\n  wishlists: Map<string, { ownerId: string; name: string }>;\n  members: Map<string, Map<string, Member>>;\n  links: Map<string, { wishlistId: string; active: boolean }>;\n  activeLink: Map<string, string>;\n};\n\nexport type WishlistState = {\n  /** Append-only membership log. */\n  log: MembershipEvent[];\n  view: MembershipView;\n  /** Items are a per-wishlist key-value set, keyed by product ID in insertion order. */\n  items: Map<string, Map<string, { addedBy: string }>>;\n};\n\ntype WithoutSeq<E> = E extends unknown ? Omit<E, \"seq\"> : never;\ntype NewEvent = WithoutSeq<MembershipEvent>;\n\nconst emptyView = (): MembershipView => ({\n  wishlists: new Map(),\n  members: new Map(),\n  links: new Map(),\n  activeLink: new Map(),\n});\n\nexport function createWishlistState(): WishlistState {\n  return { log: [], view: emptyView(), items: new Map() };\n}\n\n/** Folds one event into the materialized view. Deterministic: replaying the log gives the same view. */\nexport function apply(view: MembershipView, e: MembershipEvent): void {\n  switch (e.type) {\n    case \"created\":\n      view.wishlists.set(e.wishlistId, { ownerId: e.userId, name: e.name });\n      view.members.set(e.wishlistId, new Map([[e.userId, { role: \"owner\", via: null }]]));\n      return;\n    case \"joined\":\n      view.members.get(e.wishlistId)?.set(e.userId, { role: \"editor\", via: e.via });\n      return;\n    case \"removed\":\n      view.members.get(e.wishlistId)?.delete(e.userId);\n      return;\n    case \"link_created\":\n      view.links.set(e.token, { wishlistId: e.wishlistId, active: true });\n      view.activeLink.set(e.wishlistId, e.token);\n      return;\n    case \"link_revoked\": {\n      const link = view.links.get(e.token);\n      if (link) link.active = false;\n      if (view.activeLink.get(e.wishlistId) === e.token) view.activeLink.delete(e.wishlistId);\n      // Members who joined through the revoked link lose access.\n      const members = view.members.get(e.wishlistId);\n      for (const [userId, member] of members ?? []) {\n        if (member.via === e.token) members?.delete(userId);\n      }\n      return;\n    }\n  }\n}\n\n/** Rebuilds the materialized view from the log alone. */\nexport function replay(log: readonly MembershipEvent[]): MembershipView {\n  const view = emptyView();\n  for (const e of log) apply(view, e);\n  return view;\n}\n\nfunction append(s: WishlistState, event: NewEvent): void {\n  const e = Object.freeze({ ...event, seq: s.log.length + 1 }) as MembershipEvent;\n  s.log.push(e);\n  apply(s.view, e);\n}\n\nconst roleOf = (s: WishlistState, id: string, userId: string): Role | null =>\n  s.view.members.get(id)?.get(userId)?.role ?? null;\n\nfunction access(s: WishlistState, id: string, userId: string): Result<Role> {\n  if (!s.view.wishlists.has(id)) return err(\"not_found\");\n  const role = roleOf(s, id, userId);\n  return role ? ok(role) : err(\"forbidden\");\n}\n\nexport function createWishlist(s: WishlistState, ownerId: string, name: unknown): Result<string> {\n  if (!validName(name)) return err(\"invalid_name\");\n  const id = `wl_${crypto.randomUUID()}`;\n  append(s, { type: \"created\", wishlistId: id, userId: ownerId, name: name.trim() });\n  s.items.set(id, new Map());\n  return ok(id);\n}\n\nexport function viewWishlist(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  lookup: Lookup,\n): Result<WishlistView> {\n  const role = access(s, id, userId);\n  if (!role.ok) return role;\n  const wishlist = s.view.wishlists.get(id);\n  const members = s.view.members.get(id) ?? new Map<string, Member>();\n  const items = [...(s.items.get(id) ?? [])].map(([productId, item]) => {\n    const product = lookup(productId);\n    return {\n      productId,\n      name: product?.name ?? \"Unknown product\",\n      priceCents: product?.priceCents ?? 0,\n      addedBy: item.addedBy,\n      addedByRole: members.get(item.addedBy)?.role ?? null,\n    };\n  });\n  const collaborators = [...members]\n    .map(([memberId, m]) => ({ userId: memberId, role: m.role }))\n    .sort((a, b) =>\n      a.role === b.role ? a.userId.localeCompare(b.userId) : a.role === \"owner\" ? -1 : 1,\n    );\n  return ok({\n    id,\n    name: wishlist?.name ?? \"\",\n    owner: wishlist?.ownerId ?? \"\",\n    collaborators,\n    items,\n    itemCount: items.length,\n  });\n}\n\nexport function shareWishlist(s: WishlistState, id: string, userId: string): Result<string> {\n  const role = access(s, id, userId);\n  if (!role.ok) return role;\n  if (role.value !== \"owner\") return err(\"forbidden\");\n  const existing = s.view.activeLink.get(id);\n  if (existing) return ok(existing);\n  const token = crypto.randomUUID();\n  append(s, { type: \"link_created\", wishlistId: id, token });\n  return ok(token);\n}\n\nexport function revokeShareLink(s: WishlistState, id: string, userId: string): Result<null> {\n  const role = access(s, id, userId);\n  if (!role.ok) return role;\n  if (role.value !== \"owner\") return err(\"forbidden\");\n  const token = s.view.activeLink.get(id);\n  if (token) append(s, { type: \"link_revoked\", wishlistId: id, token });\n  return ok(null);\n}\n\nexport function joinByLink(s: WishlistState, token: string, userId: string): Result<string> {\n  const link = s.view.links.get(token);\n  if (!link?.active) return err(\"invalid_link\");\n  if (!roleOf(s, link.wishlistId, userId)) {\n    append(s, { type: \"joined\", wishlistId: link.wishlistId, userId, via: token });\n  }\n  return ok(link.wishlistId);\n}\n\nexport function addItem(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  productId: string,\n  lookup: Lookup,\n): Result<null> {\n  const role = access(s, id, userId);\n  if (!role.ok) return role;\n  if (!lookup(productId)) return err(\"unknown_product\");\n  const items = s.items.get(id) ?? new Map<string, { addedBy: string }>();\n  if (!items.has(productId)) items.set(productId, { addedBy: userId });\n  s.items.set(id, items);\n  return ok(null);\n}\n\nexport function removeItem(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  productId: string,\n): Result<null> {\n  const role = access(s, id, userId);\n  if (!role.ok) return role;\n  if (!s.items.get(id)?.delete(productId)) return err(\"not_in_wishlist\");\n  return ok(null);\n}\n\nexport function removeCollaborator(\n  s: WishlistState,\n  id: string,\n  userId: string,\n  targetId: string,\n): Result<null> {\n  const role = access(s, id, userId);\n  if (!role.ok) return role;\n  if (role.value !== \"owner\") return err(\"forbidden\");\n  if (roleOf(s, id, targetId) !== \"editor\") return err(\"not_a_collaborator\");\n  append(s, { type: \"removed\", wishlistId: id, userId: targetId });\n  return ok(null);\n}\n\n/** Bulk load: appends the events each wishlist's history implies, without per-row checks. */\nexport function importWishlists(s: WishlistState, rows: readonly SeedWishlist[]): void {\n  for (const w of rows) {\n    append(s, { type: \"created\", wishlistId: w.id, userId: w.ownerId, name: w.name });\n    if (w.shareToken) append(s, { type: \"link_created\", wishlistId: w.id, token: w.shareToken });\n    for (const userId of w.collaborators) {\n      append(s, { type: \"joined\", wishlistId: w.id, userId, via: w.shareToken ?? \"import\" });\n    }\n    s.items.set(w.id, new Map(w.items.map((i) => [i.productId, { addedBy: i.addedBy }])));\n  }\n}\n",
  "files/design-b/test/wishlist.model.test.ts": "// Design B: the membership log is append-only and the materialized view equals its replay.\nimport { expect, test } from \"bun:test\";\nimport { SEED_PRODUCTS } from \"../src/catalog\";\nimport {\n  addItem,\n  createWishlist,\n  createWishlistState,\n  joinByLink,\n  removeCollaborator,\n  replay,\n  revokeShareLink,\n  shareWishlist,\n} from \"../src/wishlist/model\";\n\nconst lookup = (id: string) => SEED_PRODUCTS.find((p) => p.id === id);\nconst must = <T>(r: { ok: true; value: T } | { ok: false; error: string }): T => {\n  if (!r.ok) throw new Error(r.error);\n  return r.value;\n};\n\ntest(\"revoking a link appends an event and keeps earlier events\", () => {\n  const s = createWishlistState();\n  const id = must(createWishlist(s, \"alice\", \"Gifts\"));\n  must(joinByLink(s, must(shareWishlist(s, id, \"alice\")), \"bob\"));\n  const before = s.log.map((e) => ({ ...e }));\n\n  must(revokeShareLink(s, id, \"alice\"));\n  expect(s.log.slice(0, before.length)).toEqual(before);\n  expect(s.log.at(-1)?.type).toBe(\"link_revoked\");\n  expect(s.log.map((e) => e.seq)).toEqual(s.log.map((_, i) => i + 1));\n  expect(Object.isFrozen(s.log[0])).toBe(true);\n  expect(addItem(s, id, \"bob\", \"p-100\", lookup)).toEqual({ ok: false, error: \"forbidden\" });\n});\n\ntest(\"the materialized members equal a replay of the log\", () => {\n  const s = createWishlistState();\n  const id = must(createWishlist(s, \"alice\", \"Gifts\"));\n  must(joinByLink(s, must(shareWishlist(s, id, \"alice\")), \"bob\"));\n  must(revokeShareLink(s, id, \"alice\"));\n  must(joinByLink(s, must(shareWishlist(s, id, \"alice\")), \"carol\"));\n  must(joinByLink(s, must(shareWishlist(s, id, \"alice\")), \"bob\"));\n  must(removeCollaborator(s, id, \"alice\", \"carol\"));\n  expect(replay(s.log)).toEqual(s.view);\n  expect([...(s.view.members.get(id)?.keys() ?? [])].sort()).toEqual([\"alice\", \"bob\"]);\n});\n",
  "files/shared/bench/api.bench.ts": "/**\n * API benchmark. Runs each endpoint benchmark in its own process and prints the slowest\n * endpoint's p95 as the API p95: {\"p95Ms\": n, \"endpoints\": {...}} on the last line.\n */\nconst BENCHES: readonly [string, string][] = [\n  [\"GET /api/cart\", \"bench/cart.bench.ts\"],\n  [\"wishlist API\", \"bench/wishlist.bench.ts\"],\n];\n\nconst endpoints: Record<string, number> = {};\nfor (const [name, file] of BENCHES) {\n  const run = Bun.spawnSync([process.execPath, \"run\", file], { stdout: \"pipe\", stderr: \"inherit\" });\n  const line = run.stdout\n    .toString()\n    .trim()\n    .split(\"\\n\")\n    .reverse()\n    .find((l) => l.startsWith(\"{\"));\n  const p95 = line ? (JSON.parse(line) as { p95Ms?: unknown }).p95Ms : undefined;\n  if (run.exitCode !== 0 || typeof p95 !== \"number\") {\n    console.error(`${file} failed (exit ${run.exitCode}); no p95 for ${name}`);\n    process.exit(1);\n  }\n  endpoints[name] = p95;\n  process.stdout.write(`${JSON.stringify({ endpoint: name, endpointP95Ms: p95 })}\\n`);\n}\n\nconst p95Ms = Math.max(...Object.values(endpoints));\nprocess.stdout.write(`${JSON.stringify({ p95Ms, endpoints })}\\n`);\n",
  "files/shared/bench/wishlist.bench.ts": "/**\n * Wishlist API benchmark. Budget: Wishlist API p95 < 200 ms in the demo benchmark.\n * Loads one deterministic shop dataset, then replays the requests a busy shared wishlist sees:\n * 80% reads, 20% item adds and removes, all as a collaborator. Prints {\"p95Ms\": n, ...}.\n * The dataset and request mix are the same for every wishlist data model.\n */\nimport { createApp } from \"../src/app\";\nimport { createStore } from \"../src/store\";\nimport { importWishlists } from \"../src/wishlist/model\";\nimport type { SeedWishlist } from \"../src/wishlist/types\";\n\nconst WISHLISTS = 30_000;\nconst MAX_SAMPLES = 300;\n/** Stop sampling after this much wall time, with at least MIN_SAMPLES samples. */\nconst BUDGET_MS = 15_000;\nconst MIN_SAMPLES = 12;\nconst PRODUCTS = 2_000;\nconst USERS = 50_000;\nconst HOT = \"wl-hot\";\n\n// mulberry32: a fixed seed gives the same dataset on every run and for every design.\nfunction random(seed: number) {\n  let a = seed >>> 0;\n  return () => {\n    a = (a + 0x6d2b79f5) >>> 0;\n    let t = a;\n    t = Math.imul(t ^ (t >>> 15), t | 1);\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\nconst rand = random(1841);\nconst int = (min: number, max: number) => min + Math.floor(rand() * (max - min + 1));\nconst user = () => `u-${String(int(1, USERS)).padStart(5, \"0\")}`;\nconst product = (i: number) => `p-${1000 + i}`;\n\nconst store = createStore();\nfor (let i = 0; i < PRODUCTS; i++) {\n  store.products.set(product(i), {\n    id: product(i),\n    name: `Catalog item ${i}`,\n    priceCents: 500 + ((i * 37) % 20_000),\n  });\n}\n\nfunction wishlist(\n  id: string,\n  ownerId: string,\n  collaborators: string[],\n  items: number,\n): SeedWishlist {\n  const members = [ownerId, ...collaborators];\n  const start = int(0, PRODUCTS - items);\n  return {\n    id,\n    ownerId,\n    name: `List ${id}`,\n    collaborators,\n    shareToken: `link-${id}`,\n    items: Array.from({ length: items }, (_, k) => ({\n      productId: product(start + k),\n      addedBy: members[k % members.length] ?? ownerId,\n    })),\n  };\n}\n\nconst rows: SeedWishlist[] = [];\nfor (let i = 0; i < WISHLISTS; i++) {\n  const collaborators = Array.from({ length: int(2, 20) }, user);\n  rows.push(wishlist(`wl-${i}`, user(), collaborators, int(1, 15)));\n}\n// The shared wishlist under load: the newest list, shared with a large family, many products.\nrows.push(wishlist(HOT, \"alice\", [\"bob\", \"carol\", ...Array.from({ length: 40 }, user)], 120));\nimportWishlists(store.wishlists, rows);\nconst dataset = {\n  wishlists: rows.length,\n  memberships: rows.reduce((n, w) => n + 1 + w.collaborators.length, 0),\n  items: rows.reduce((n, w) => n + w.items.length, 0),\n};\nconst app = createApp(store);\n\nconst headers = { \"x-user-id\": \"bob\", \"content-type\": \"application/json\" };\nasync function request(i: number) {\n  const slot = i % 10;\n  const productId = product(PRODUCTS - 1 - ((i / 10) | 0));\n  const res =\n    slot === 8\n      ? await app.request(`/api/wishlists/${HOT}/items`, {\n          method: \"POST\",\n          headers,\n          body: JSON.stringify({ productId }),\n        })\n      : slot === 9\n        ? await app.request(`/api/wishlists/${HOT}/items/${productId}`, {\n            method: \"DELETE\",\n            headers,\n          })\n        : await app.request(`/api/wishlists/${HOT}`, { headers });\n  if (res.status >= 300) throw new Error(`request ${i} returned ${res.status}`);\n  await res.arrayBuffer();\n}\n\nconst samples: number[] = [];\nconst began = performance.now();\nfor (let i = 0; i < MAX_SAMPLES; i++) {\n  if (samples.length >= MIN_SAMPLES && performance.now() - began > BUDGET_MS) break;\n  const start = performance.now();\n  await request(i);\n  samples.push(performance.now() - start);\n}\n\nsamples.sort((a, b) => a - b);\nconst p95Ms = samples[Math.min(samples.length - 1, Math.ceil(samples.length * 0.95) - 1)] ?? 0;\nprocess.stdout.write(\n  `${JSON.stringify({\n    p95Ms,\n    samples: samples.length,\n    dataset,\n  })}\\n`,\n);\n",
  "files/shared/public/wishlist.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Acme Shop - Wishlists</title>\n    <style>\n      body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2rem auto; padding: 0 1rem; }\n      li { margin: 0.4rem 0; }\n      #error { color: #b00020; }\n      input[readonly] { width: 100%; }\n    </style>\n  </head>\n  <body>\n    <h1><a href=\"/\">Acme Shop</a> / Wishlists</h1>\n    <p>\n      Signed in as\n      <select id=\"user\">\n        <option>alice</option>\n        <option>bob</option>\n        <option>carol</option>\n      </select>\n    </p>\n    <form id=\"create\">\n      <input id=\"name\" placeholder=\"New wishlist name\" required />\n      <button type=\"submit\">Create wishlist</button>\n    </form>\n    <p id=\"error\"></p>\n    <section id=\"wishlist\" hidden>\n      <h2 id=\"title\">Wishlist</h2>\n      <p id=\"share-box\">\n        <button id=\"share\" type=\"button\">Share with a link</button>\n        <button id=\"revoke\" type=\"button\">Revoke link</button>\n        <input id=\"share-url\" readonly hidden />\n      </p>\n      <h3>Items</h3>\n      <ul id=\"items\"></ul>\n      <h3>Collaborators</h3>\n      <ul id=\"collaborators\"></ul>\n      <h3>Add products</h3>\n      <ul id=\"products\"></ul>\n    </section>\n    <script>\n      const $ = (id) => document.getElementById(id);\n      const money = (c) => `$${(c / 100).toFixed(2)}`;\n      const params = new URLSearchParams(location.search);\n      let current = params.get(\"id\");\n      $(\"user\").value = params.get(\"as\") || \"alice\";\n\n      async function api(path, init = {}) {\n        const res = await fetch(`/api${path}`, {\n          ...init,\n          headers: { \"x-user-id\": $(\"user\").value, \"content-type\": \"application/json\" },\n        });\n        const body = await res.json().catch(() => ({}));\n        $(\"error\").textContent = res.ok ? \"\" : `${res.status}: ${body.error || \"request failed\"}`;\n        return res.ok ? body : null;\n      }\n\n      function render(w) {\n        if (!w) return;\n        current = w.id;\n        history.replaceState(null, \"\", `?id=${w.id}&as=${$(\"user\").value}`);\n        const owner = w.owner === $(\"user\").value;\n        $(\"wishlist\").hidden = false;\n        $(\"title\").textContent = `${w.name} (owner: ${w.owner})`;\n        $(\"share-box\").hidden = !owner;\n        $(\"items\").innerHTML = w.items\n          .map((i) => `<li>${i.name} ${money(i.priceCents)}, added by ${i.addedBy}\n            <button data-remove=\"${i.productId}\">Remove</button></li>`)\n          .join(\"\") || \"<li>No items yet</li>\";\n        $(\"collaborators\").innerHTML = w.collaborators\n          .map((c) => `<li>${c.userId} (${c.role})${owner && c.role === \"editor\"\n            ? ` <button data-kick=\"${c.userId}\">Remove</button>` : \"\"}</li>`)\n          .join(\"\");\n      }\n\n      const load = async () => current && render(await api(`/wishlists/${current}`));\n\n      $(\"create\").addEventListener(\"submit\", async (e) => {\n        e.preventDefault();\n        render(await api(\"/wishlists\", { method: \"POST\", body: JSON.stringify({ name: $(\"name\").value }) }));\n      });\n      $(\"share\").addEventListener(\"click\", async () => {\n        const link = await api(`/wishlists/${current}/share`, { method: \"POST\" });\n        if (!link) return;\n        $(\"share-url\").hidden = false;\n        $(\"share-url\").value = `${location.origin}/wishlist.html?join=${link.token}`;\n      });\n      $(\"revoke\").addEventListener(\"click\", async () => {\n        $(\"share-url\").hidden = true;\n        render(await api(`/wishlists/${current}/share`, { method: \"DELETE\" }));\n      });\n      $(\"user\").addEventListener(\"change\", load);\n      document.addEventListener(\"click\", async (e) => {\n        const { add, remove, kick } = e.target.dataset;\n        if (add) render(await api(`/wishlists/${current}/items`, { method: \"POST\", body: JSON.stringify({ productId: add }) }));\n        if (remove) render(await api(`/wishlists/${current}/items/${remove}`, { method: \"DELETE\" }));\n        if (kick) render(await api(`/wishlists/${current}/collaborators/${kick}`, { method: \"DELETE\" }));\n      });\n\n      (async () => {\n        const { products } = (await api(\"/products\")) || { products: [] };\n        $(\"products\").innerHTML = products\n          .map((p) => `<li>${p.name} (${money(p.priceCents)})\n            <button data-add=\"${p.id}\">Add to wishlist</button></li>`)\n          .join(\"\");\n        const token = params.get(\"join\");\n        if (token) {\n          if (!params.get(\"as\")) $(\"user\").value = \"bob\";\n          render(await api(`/wishlist-links/${token}/join`, { method: \"POST\" }));\n        } else {\n          await load();\n        }\n      })();\n    </script>\n  </body>\n</html>\n",
  "files/shared/src/wishlist/routes.ts": "import type { Context, Hono } from \"hono\";\nimport type { UserId } from \"../identity\";\nimport type { Store } from \"../store\";\nimport {\n  addItem,\n  createWishlist,\n  joinByLink,\n  removeCollaborator,\n  removeItem,\n  revokeShareLink,\n  shareWishlist,\n  viewWishlist,\n} from \"./model\";\nimport type { Result, WishlistError } from \"./types\";\n\ntype Env = { Variables: { user: UserId } };\n\nconst STATUS: Record<WishlistError, 400 | 403 | 404> = {\n  invalid_name: 400,\n  not_found: 404,\n  forbidden: 403,\n  unknown_product: 404,\n  not_in_wishlist: 404,\n  invalid_link: 404,\n  not_a_collaborator: 404,\n};\n\nconst body = async (c: Context<Env>): Promise<Record<string, unknown>> => {\n  const parsed: unknown = await c.req.json().catch(() => null);\n  return typeof parsed === \"object\" && parsed !== null ? (parsed as Record<string, unknown>) : {};\n};\n\n/**\n * Shared wishlists: create, share by link, collaborators add and remove products, the owner\n * revokes the link or removes a collaborator. Every route needs the fixture user (x-user-id).\n */\nexport function registerWishlistRoutes(app: Hono<Env>, store: Store) {\n  const state = store.wishlists;\n  const lookup = (id: string) => store.products.get(id);\n\n  // Returns the wishlist as `viewer` after a successful command, or the command's error.\n  const reply = (c: Context<Env>, result: Result<unknown>, id: string, status: 200 | 201 = 200) => {\n    if (!result.ok) return c.json({ error: result.error }, STATUS[result.error]);\n    const view = viewWishlist(state, id, c.get(\"user\"), lookup);\n    if (!view.ok) return c.json({ error: view.error }, STATUS[view.error]);\n    return c.json(view.value, status);\n  };\n\n  app.post(\"/api/wishlists\", async (c) => {\n    const created = createWishlist(state, c.get(\"user\"), (await body(c)).name);\n    return created.ok ? reply(c, created, created.value, 201) : reply(c, created, \"\");\n  });\n\n  app.get(\"/api/wishlists/:id\", (c) => reply(c, { ok: true, value: null }, c.req.param(\"id\")));\n\n  app.post(\"/api/wishlists/:id/share\", (c) => {\n    const id = c.req.param(\"id\");\n    const shared = shareWishlist(state, id, c.get(\"user\"));\n    if (!shared.ok) return c.json({ error: shared.error }, STATUS[shared.error]);\n    return c.json(\n      { token: shared.value, joinPath: `/api/wishlist-links/${shared.value}/join` },\n      201,\n    );\n  });\n\n  app.delete(\"/api/wishlists/:id/share\", (c) => {\n    const id = c.req.param(\"id\");\n    return reply(c, revokeShareLink(state, id, c.get(\"user\")), id);\n  });\n\n  app.post(\"/api/wishlist-links/:token/join\", (c) => {\n    const joined = joinByLink(state, c.req.param(\"token\"), c.get(\"user\"));\n    return joined.ok ? reply(c, joined, joined.value) : reply(c, joined, \"\");\n  });\n\n  app.post(\"/api/wishlists/:id/items\", async (c) => {\n    const id = c.req.param(\"id\");\n    const productId = (await body(c)).productId;\n    const added =\n      typeof productId === \"string\"\n        ? addItem(state, id, c.get(\"user\"), productId, lookup)\n        : ({ ok: false, error: \"unknown_product\" } as const);\n    return reply(c, added, id, 201);\n  });\n\n  app.delete(\"/api/wishlists/:id/items/:productId\", (c) => {\n    const id = c.req.param(\"id\");\n    return reply(c, removeItem(state, id, c.get(\"user\"), c.req.param(\"productId\")), id);\n  });\n\n  app.delete(\"/api/wishlists/:id/collaborators/:userId\", (c) => {\n    const id = c.req.param(\"id\");\n    return reply(c, removeCollaborator(state, id, c.get(\"user\"), c.req.param(\"userId\")), id);\n  });\n}\n",
  "files/shared/src/wishlist/types.ts": "// Shared wishlist contract. Both data models implement the functions in ./model with these types,\n// so the HTTP routes, tests, and benchmark are the same for every design.\nimport type { Product } from \"../catalog\";\n\nexport type Role = \"owner\" | \"editor\";\n\nexport type WishlistItemView = {\n  productId: string;\n  name: string;\n  priceCents: number;\n  addedBy: string;\n  /** Current role of the user who added the item, or null when they are no longer a member. */\n  addedByRole: Role | null;\n};\n\nexport type WishlistView = {\n  id: string;\n  name: string;\n  owner: string;\n  collaborators: { userId: string; role: Role }[];\n  items: WishlistItemView[];\n  itemCount: number;\n};\n\nexport type WishlistError =\n  | \"invalid_name\"\n  | \"not_found\"\n  | \"forbidden\"\n  | \"unknown_product\"\n  | \"not_in_wishlist\"\n  | \"invalid_link\"\n  | \"not_a_collaborator\";\n\nexport type Result<T> = { ok: true; value: T } | { ok: false; error: WishlistError };\n\nexport type Lookup = (productId: string) => Product | undefined;\n\n/** Bulk-load shape for fixtures and benchmarks: one wishlist with its members and items. */\nexport type SeedWishlist = {\n  id: string;\n  ownerId: string;\n  name: string;\n  /** Editors who joined through the wishlist's share link. */\n  collaborators: string[];\n  shareToken: string | null;\n  items: { productId: string; addedBy: string }[];\n};\n\nexport const ok = <T>(value: T): Result<T> => ({ ok: true, value });\nexport const err = <T>(error: WishlistError): Result<T> => ({ ok: false, error });\n\nexport function validName(name: unknown): name is string {\n  return typeof name === \"string\" && name.trim().length > 0 && name.length <= 80;\n}\n",
  "files/shared/test/wishlist.acceptance.test.ts": "// Shared wishlist acceptance tests. They use only the HTTP API, so they hold for every data model.\n// Tests named \"authorization ...\" are the security check (bun test --test-name-pattern authorization).\nimport { describe, expect, test } from \"bun:test\";\nimport { createApp } from \"../src/app\";\nimport { createStore } from \"../src/store\";\nimport type { WishlistView } from \"../src/wishlist/types\";\n\ntype App = ReturnType<typeof createApp>;\n\nconst send = (app: App, user: string, method: string, path: string, body?: unknown) =>\n  app.request(path, {\n    method,\n    headers: { \"x-user-id\": user, \"content-type\": \"application/json\" },\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n\nasync function setup() {\n  const app = createApp(createStore());\n  const created = await send(app, \"alice\", \"POST\", \"/api/wishlists\", { name: \"Camping trip\" });\n  expect(created.status).toBe(201);\n  const { id } = (await created.json()) as WishlistView;\n  return { app, id };\n}\n\nasync function shareAndJoin(app: App, id: string, user: string) {\n  const shared = await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/share`);\n  expect(shared.status).toBe(201);\n  const { token, joinPath } = (await shared.json()) as { token: string; joinPath: string };\n  expect(joinPath).toBe(`/api/wishlist-links/${token}/join`);\n  expect((await send(app, user, \"POST\", joinPath)).status).toBe(200);\n  return { token, joinPath };\n}\n\nconst view = async (app: App, user: string, id: string) =>\n  (await (await send(app, user, \"GET\", `/api/wishlists/${id}`)).json()) as WishlistView;\n\ndescribe(\"wishlists\", () => {\n  test(\"owner creates a wishlist and adds products\", async () => {\n    const { app, id } = await setup();\n    const added = await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-103\",\n    });\n    expect(added.status).toBe(201);\n    expect(await added.json()).toEqual({\n      id,\n      name: \"Camping trip\",\n      owner: \"alice\",\n      collaborators: [{ userId: \"alice\", role: \"owner\" }],\n      items: [\n        {\n          productId: \"p-103\",\n          name: \"Headlamp\",\n          priceCents: 3500,\n          addedBy: \"alice\",\n          addedByRole: \"owner\",\n        },\n      ],\n      itemCount: 1,\n    });\n  });\n\n  test(\"adding the same product twice keeps one line\", async () => {\n    const { app, id } = await setup();\n    await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/items`, { productId: \"p-100\" });\n    await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/items`, { productId: \"p-100\" });\n    expect((await view(app, \"alice\", id)).itemCount).toBe(1);\n  });\n\n  test(\"validation errors\", async () => {\n    const { app, id } = await setup();\n    expect((await send(app, \"alice\", \"POST\", \"/api/wishlists\", { name: \" \" })).status).toBe(400);\n    expect((await send(app, \"alice\", \"GET\", \"/api/wishlists/wl_missing\")).status).toBe(404);\n    const unknown = await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"nope\",\n    });\n    expect(unknown.status).toBe(404);\n    expect((await send(app, \"alice\", \"DELETE\", `/api/wishlists/${id}/items/p-100`)).status).toBe(\n      404,\n    );\n  });\n\n  test(\"wishlist actions leave the cart unchanged\", async () => {\n    const { app, id } = await setup();\n    await send(app, \"alice\", \"POST\", \"/api/cart/items\", { productId: \"p-101\", quantity: 2 });\n    const before = await (await send(app, \"alice\", \"GET\", \"/api/cart\")).json();\n    await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/items`, { productId: \"p-101\" });\n    await send(app, \"alice\", \"DELETE\", `/api/wishlists/${id}/items/p-101`);\n    expect(await (await send(app, \"alice\", \"GET\", \"/api/cart\")).json()).toEqual(before);\n  });\n});\n\ndescribe(\"wishlist sharing\", () => {\n  test(\"authorization: non-members cannot read or change a wishlist\", async () => {\n    const { app, id } = await setup();\n    expect((await send(app, \"bob\", \"GET\", `/api/wishlists/${id}`)).status).toBe(403);\n    const write = await send(app, \"bob\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-100\",\n    });\n    expect(write.status).toBe(403);\n    expect((await send(app, \"mallory\", \"GET\", `/api/wishlists/${id}`)).status).toBe(401);\n  });\n\n  test(\"authorization: a share link lets a collaborator add and remove products\", async () => {\n    const { app, id } = await setup();\n    await send(app, \"alice\", \"POST\", `/api/wishlists/${id}/items`, { productId: \"p-100\" });\n    await shareAndJoin(app, id, \"bob\");\n\n    const added = await send(app, \"bob\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-104\",\n    });\n    expect(added.status).toBe(201);\n    const removed = await send(app, \"bob\", \"DELETE\", `/api/wishlists/${id}/items/p-100`);\n    expect(removed.status).toBe(200);\n\n    // The owner sees the collaborator's changes.\n    const owner = await view(app, \"alice\", id);\n    expect(owner.collaborators).toEqual([\n      { userId: \"alice\", role: \"owner\" },\n      { userId: \"bob\", role: \"editor\" },\n    ]);\n    expect(owner.items.map((i) => [i.productId, i.addedBy, i.addedByRole])).toEqual([\n      [\"p-104\", \"bob\", \"editor\"],\n    ]);\n  });\n\n  test(\"authorization: only the owner shares, revokes, or removes collaborators\", async () => {\n    const { app, id } = await setup();\n    await shareAndJoin(app, id, \"bob\");\n    expect((await send(app, \"bob\", \"POST\", `/api/wishlists/${id}/share`)).status).toBe(403);\n    expect((await send(app, \"bob\", \"DELETE\", `/api/wishlists/${id}/share`)).status).toBe(403);\n    const kick = await send(app, \"bob\", \"DELETE\", `/api/wishlists/${id}/collaborators/alice`);\n    expect(kick.status).toBe(403);\n  });\n\n  test(\"authorization: revoking the link denies later collaborator writes\", async () => {\n    const { app, id } = await setup();\n    const { joinPath } = await shareAndJoin(app, id, \"bob\");\n    await send(app, \"bob\", \"POST\", `/api/wishlists/${id}/items`, { productId: \"p-102\" });\n\n    const revoked = await send(app, \"alice\", \"DELETE\", `/api/wishlists/${id}/share`);\n    expect(revoked.status).toBe(200);\n    expect(((await revoked.json()) as WishlistView).collaborators).toEqual([\n      { userId: \"alice\", role: \"owner\" },\n    ]);\n\n    const write = await send(app, \"bob\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-105\",\n    });\n    expect(write.status).toBe(403);\n    expect((await send(app, \"bob\", \"DELETE\", `/api/wishlists/${id}/items/p-102`)).status).toBe(403);\n    // The old link no longer admits anyone.\n    expect((await send(app, \"carol\", \"POST\", joinPath)).status).toBe(404);\n    expect((await send(app, \"bob\", \"POST\", joinPath)).status).toBe(404);\n    // Items the removed collaborator added stay, attributed to a non-member.\n    const owner = await view(app, \"alice\", id);\n    expect(owner.items.map((i) => [i.productId, i.addedByRole])).toEqual([[\"p-102\", null]]);\n  });\n\n  test(\"authorization: a new link works after a revoke, the old one stays dead\", async () => {\n    const { app, id } = await setup();\n    const first = await shareAndJoin(app, id, \"bob\");\n    await send(app, \"alice\", \"DELETE\", `/api/wishlists/${id}/share`);\n    const second = await shareAndJoin(app, id, \"carol\");\n    expect(second.token).not.toBe(first.token);\n    expect((await send(app, \"bob\", \"POST\", first.joinPath)).status).toBe(404);\n    const write = await send(app, \"carol\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-106\",\n    });\n    expect(write.status).toBe(201);\n  });\n\n  test(\"authorization: removing a collaborator denies their writes\", async () => {\n    const { app, id } = await setup();\n    await shareAndJoin(app, id, \"bob\");\n    await shareAndJoin(app, id, \"carol\");\n    const removed = await send(app, \"alice\", \"DELETE\", `/api/wishlists/${id}/collaborators/bob`);\n    expect(removed.status).toBe(200);\n    const write = await send(app, \"bob\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-100\",\n    });\n    expect(write.status).toBe(403);\n    expect((await send(app, \"bob\", \"GET\", `/api/wishlists/${id}`)).status).toBe(403);\n    // Carol still has access.\n    const carol = await send(app, \"carol\", \"POST\", `/api/wishlists/${id}/items`, {\n      productId: \"p-100\",\n    });\n    expect(carol.status).toBe(201);\n  });\n});\n",
  "manifest.ts": "/**\n * Wishlist design-conflict fixture. Two complete, independently verifiable implementations of\n * shared wishlists on top of `fixtures/acme-shop`:\n *\n * - Design A: normalized mutable collaborator membership table. Access is derived from the table on\n *   every request, so a read costs O(membership rows) per check and the item list does one check\n *   per item. On the benchmark dataset this misses the p95 budget.\n * - Design B: append-only membership event log with a materialized current-member set. Reads use\n *   the set directly and pass the budget.\n *\n * Both designs have the same HTTP contract, acceptance tests, and benchmark (`files/shared`), and\n * each declares the Intent an agent would declare for it. Fixture-sourced: no model produced them.\n */\n\nexport type WishlistDesign = \"a\" | \"b\";\n\n/** Text replacement in an existing canonical file. `find` must occur exactly once. */\nexport type SourceEdit = { path: string; find: string; replace: string };\n\n/** The `complete_task` Intent declaration, as agents store it in `changesets.intent_json`. */\nexport type DeclaredIntent = {\n  summary: string;\n  semanticResources: string[];\n  expectedFiles: string[];\n  expectedContractChanges: string[];\n  expectedDataChanges: string[];\n  assumptions: string[];\n  acceptanceEvidence: string[];\n};\n\nexport type DesignFixture = {\n  design: WishlistDesign;\n  /** Work Graph task key; Task, run, fork, and ChangeSet IDs derive from it. */\n  taskKey: string;\n  title: string;\n  objective: string;\n  agentId: string;\n  /** Directories under `files/` copied into the repo root, in order. */\n  sources: string[];\n  edits: SourceEdit[];\n  intent: Omit<DeclaredIntent, \"expectedFiles\">;\n  commitMessage: string;\n};\n\n/** The demo user goal, word for word. */\nexport const WISHLIST_GOAL =\n  \"Add shared wishlists. Users can create a wishlist, share it with a link, and let collaborators \" +\n  \"add or remove products. Keep existing cart behavior unchanged. Keep API p95 below 200 ms.\";\n\n/** The Work Graph facts a planner would record for the Wishlist Change. */\nexport const CHANGE_PLAN = {\n  riskTier: \"high\",\n  acceptanceCriteria: [\n    \"A user can create a wishlist.\",\n    \"The owner can share a wishlist with a link.\",\n    \"Collaborators who join through the link can add and remove products.\",\n    \"Revoking the link denies later collaborator writes.\",\n    \"Wishlist API p95 stays below 200 ms in the demo benchmark.\",\n  ],\n  invariants: [\"Existing cart add, remove, quantity, and total behavior must remain unchanged.\"],\n} as const;\n\n/** Wiring both designs share: the store holds wishlist state, the app mounts the routes. */\nconst EDITS: SourceEdit[] = [\n  {\n    path: \"src/store.ts\",\n    find: 'import type { UserId } from \"./identity\";\\n',\n    replace:\n      'import type { UserId } from \"./identity\";\\n' +\n      'import { createWishlistState, type WishlistState } from \"./wishlist/model\";\\n',\n  },\n  {\n    path: \"src/store.ts\",\n    find: \"  carts: Map<UserId, Cart>;\\n\",\n    replace: \"  carts: Map<UserId, Cart>;\\n  wishlists: WishlistState;\\n\",\n  },\n  {\n    path: \"src/store.ts\",\n    find: \"    carts: new Map(),\\n\",\n    replace: \"    carts: new Map(),\\n    wishlists: createWishlistState(),\\n\",\n  },\n  {\n    path: \"src/app.ts\",\n    find: 'import { getCart, type Store, setCart } from \"./store\";\\n',\n    replace:\n      'import { getCart, type Store, setCart } from \"./store\";\\n' +\n      'import { registerWishlistRoutes } from \"./wishlist/routes\";\\n',\n  },\n  {\n    path: \"src/app.ts\",\n    find: \"\\n  return app;\\n}\\n\",\n    replace: \"\\n  registerWishlistRoutes(app, store);\\n\\n  return app;\\n}\\n\",\n  },\n  {\n    path: \"package.json\",\n    find: '\"bench\": \"bun run bench/cart.bench.ts\",',\n    replace: '\"bench\": \"bun run bench/api.bench.ts\",',\n  },\n  {\n    path: \"public/index.html\",\n    find: \"    <h1>Acme Shop</h1>\\n\",\n    replace: '    <h1>Acme Shop</h1>\\n    <p><a href=\"/wishlist.html\">Wishlists</a></p>\\n',\n  },\n  {\n    path: \"README.md\",\n    find: \"- Identity fixture:\",\n    replace:\n      \"- Wishlists: `POST /api/wishlists`, `GET /api/wishlists/:id`, `POST|DELETE /api/wishlists/:id/share`, \" +\n      \"`POST /api/wishlist-links/:token/join`, `POST /api/wishlists/:id/items`, \" +\n      \"`DELETE /api/wishlists/:id/items/:productId`, `DELETE /api/wishlists/:id/collaborators/:userId`\\n\" +\n      \"- Identity fixture:\",\n  },\n];\n\n/** Same routes and response shapes in both designs: the contract is not where they differ. */\nconst CONTRACT = [\n  \"POST /api/wishlists - add: create a wishlist {name} returns {WishlistView}\",\n  \"GET /api/wishlists/:id - add: read a wishlist as owner or collaborator {WishlistView}\",\n  \"POST /api/wishlists/:id/share - add: owner creates or returns the share link {token,joinPath}\",\n  \"DELETE /api/wishlists/:id/share - add: owner revokes the share link {WishlistView}\",\n  \"POST /api/wishlist-links/:token/join - add: join as editor through a share link {WishlistView}\",\n  \"POST /api/wishlists/:id/items - add: owner or collaborator adds a product {productId} returns {WishlistView}\",\n  \"DELETE /api/wishlists/:id/items/:productId - add: owner or collaborator removes a product {WishlistView}\",\n  \"DELETE /api/wishlists/:id/collaborators/:userId - add: owner removes a collaborator {WishlistView}\",\n];\n\nconst EVIDENCE = [\n  \"bun run typecheck\",\n  \"bun test\",\n  \"bun test --test-name-pattern authorization\",\n  \"bun run contract\",\n  \"bun run bench\",\n];\n\nexport const DESIGNS: Record<WishlistDesign, DesignFixture> = {\n  a: {\n    design: \"a\",\n    taskKey: \"wishlist-membership-table\",\n    title: \"Shared wishlists on a normalized collaborator table\",\n    objective:\n      \"Implement shared wishlists with normalized, mutable relational tables for wishlists, \" +\n      \"collaborator memberships, share links, and items.\",\n    agentId: \"fixture-design-a\",\n    sources: [\"shared\", \"design-a\"],\n    edits: EDITS,\n    intent: {\n      summary:\n        \"Shared wishlists on normalized mutable tables: wishlist_collaborators rows are updated \" +\n        \"in place on remove and revoke, and access is read from the table on each request.\",\n      semanticResources: [\"wishlist:membership\", \"wishlist:items\"],\n      expectedContractChanges: CONTRACT,\n      expectedDataChanges: [\n        \"Add `wishlist_collaborators` table (wishlist_id, user_id, role, via_link, active): normalized mutable rows, updated in place on remove and revoke\",\n        \"Add `wishlists`, `wishlist_share_links`, and `wishlist_items` tables: normalized rows\",\n      ],\n      assumptions: [\n        \"Membership changes are rare compared with wishlist reads.\",\n        \"Effective access is recomputed from the collaborator table on every request.\",\n        \"Revoking a share link updates the collaborator rows that joined through it in place.\",\n      ],\n      acceptanceEvidence: EVIDENCE,\n    },\n    commitMessage: \"Shared wishlists: normalized mutable collaborator table (fixture design A)\",\n  },\n  b: {\n    design: \"b\",\n    taskKey: \"wishlist-membership-log\",\n    title: \"Shared wishlists on an append-only membership log\",\n    objective:\n      \"Implement shared wishlists with an append-only membership event log and a materialized \" +\n      \"current-member set.\",\n    agentId: \"fixture-design-b\",\n    sources: [\"shared\", \"design-b\"],\n    edits: EDITS,\n    intent: {\n      summary:\n        \"Shared wishlists on an append-only membership event log: joins, removals, and link \" +\n        \"revocations are appended, and reads use a materialized current-member set.\",\n      semanticResources: [\"wishlist:membership\", \"wishlist:items\"],\n      expectedContractChanges: CONTRACT,\n      expectedDataChanges: [\n        \"Add `wishlist_membership_events` append-only event log (created, joined, removed, link_created, link_revoked) ordered by seq; the current-member set is materialized from it\",\n        \"Add `wishlists` registry and `wishlist_items` key-value sets per wishlist\",\n      ],\n      assumptions: [\n        \"Membership changes can be frequent and concurrent.\",\n        \"Reads use the materialized current-member set and never recompute access from history.\",\n        \"Revoking a share link appends an event; earlier events are never changed.\",\n      ],\n      acceptanceEvidence: EVIDENCE,\n    },\n    commitMessage: \"Shared wishlists: append-only membership log (fixture design B)\",\n  },\n};\n\n/** IDs one design gets on one Change, in the agents' formats (dispatch.ts, agent-do.ts). */\nexport function fixtureIds(changeId: string, design: WishlistDesign) {\n  const taskId = `tsk_${changeId.slice(4)}_${DESIGNS[design].taskKey}`;\n  const run = `${taskId.slice(4)}_1`;\n  return {\n    taskId,\n    runId: `run_${run}`,\n    fork: `ws-${run}`,\n    changeSetId: `cs_${run}`,\n    intentId: `int_${run}`,\n  };\n}\n"
} as Record<string, string>;
